const O=1.5,N=(e,g,a)=>((e+2048)*4096+(g+2048))*4096+(a+2048);export function buildWorld(e){const g=e.length/10,a=new Float64Array(g*14),w=new Uint8Array(g),y=new Map;for(let n=0;n<g;n++){const t=n*10,s=e[t],p=e[t+1],c=e[t+2],L=e[t+3]-s,h=e[t+4]-p,f=e[t+5]-c,i=e[t+6]-s,o=e[t+7]-p,m=e[t+8]-c;let x=h*m-f*o,z=f*i-L*m,C=L*o-h*i;const v=Math.sqrt(x*x+z*z+C*C)||1;x/=v,z/=v,C/=v;const r=n*14;a[r]=s,a[r+1]=p,a[r+2]=c,a[r+3]=L,a[r+4]=h,a[r+5]=f,a[r+6]=i,a[r+7]=o,a[r+8]=m,a[r+9]=x,a[r+10]=z,a[r+11]=C,a[r+12]=x*s+z*p+C*c,w[n]=e[t+9];const E=[0,1,2].map(M=>Math.floor(Math.min(e[t+M],e[t+3+M],e[t+6+M])/1.5)),q=[0,1,2].map(M=>Math.floor(Math.max(e[t+M],e[t+3+M],e[t+6+M])/1.5));for(let M=E[0];M<=q[0];M++)for(let U=E[1];U<=q[1];U++)for(let l=E[2];l<=q[2];l++){const b=N(M,U,l);let A=y.get(b);A||y.set(b,A=[]),A.push(n)}}return{n:g,T:a,mats:w,map:y,stamp:new Uint32Array(g),gen:0}}export function query(e,g,a,w,y,n){n.length=0,e.gen=e.gen+1>>>0,e.gen===0&&(e.stamp.fill(0),e.gen=1);const t=e.gen,s=e.T;for(let p=Math.floor((g-y)/1.5);p<=Math.floor((g+y)/1.5);p++)for(let c=Math.floor((a-y)/1.5);c<=Math.floor((a+y)/1.5);c++)for(let L=Math.floor((w-y)/1.5);L<=Math.floor((w+y)/1.5);L++){const h=e.map.get(N(p,c,L));if(h)for(const f of h){if(e.stamp[f]===t)continue;e.stamp[f]=t;const i=f*14,o=s[i+9]*g+s[i+10]*a+s[i+11]*w-s[i+12];o>y||o<-y||n.push(f)}}return n}export function closest(e,g,a,w,y,n){const t=e.T,s=g*14,p=t[s],c=t[s+1],L=t[s+2],h=t[s+3],f=t[s+4],i=t[s+5],o=t[s+6],m=t[s+7],x=t[s+8],z=a-p,C=w-c,v=y-L,r=h*z+f*C+i*v,E=o*z+m*C+x*v;if(r<=0&&E<=0)return n[0]=p,n[1]=c,n[2]=L,n;const q=z-h,M=C-f,U=v-i,l=h*q+f*M+i*U,b=o*q+m*M+x*U;if(l>=0&&b<=l)return n[0]=p+h,n[1]=c+f,n[2]=L+i,n;const A=r*b-l*E;if(A<=0&&r>=0&&l<=0){const d=r/(r-l);return n[0]=p+h*d,n[1]=c+f*d,n[2]=L+i*d,n}const G=z-o,H=C-m,I=v-x,F=h*G+f*H+i*I,T=o*G+m*H+x*I;if(T>=0&&F<=T)return n[0]=p+o,n[1]=c+m,n[2]=L+x,n;const j=F*E-r*T;if(j<=0&&E>=0&&T<=0){const d=E/(E-T);return n[0]=p+o*d,n[1]=c+m*d,n[2]=L+x*d,n}const J=l*T-F*b;if(J<=0&&b-l>=0&&F-T>=0){const d=(b-l)/(b-l+(F-T));return n[0]=p+h+(o-h)*d,n[1]=c+f+(m-f)*d,n[2]=L+i+(x-i)*d,n}const K=1/(J+j+A),B=j*K,D=A*K;return n[0]=p+h*B+o*D,n[1]=c+f*B+m*D,n[2]=L+i*B+x*D,n}
